function notice(message){$('notice').textContent=message;$('notice').hidden=!message}
function popup(r){return `<div class="popup-kicker">记录 #${r.id} · ${escape(names[r.type]||r.type)}</div><h3>${escape(r.model)}</h3><div class="popup-row"><b>日期</b>${escape(r.date)}</div><div class="popup-row"><b>状态</b><span style="color:${colors[r.status]}">${escape(statuses[r.status]||r.status)}</span></div><div class="popup-row"><b>地点</b>${escape(r.nearest_location||'未注明')}</div><div class="popup-row"><b>部队</b>${escape(r.unit||'未知')}</div><div class="popup-row"><b>坐标</b>${escape(r.geo||'缺少坐标')}</div>${r.tags?`<div class="popup-row"><b>标签</b>${escape(r.tags)}</div>`:''}<div class="popup-foot"><a href="https://ukr.warspotting.net/view/${r.id}/" target="_blank" rel="noopener">查看 WarSpotting 原始记录 ↗</a></div>`}
