function renderTimeline(){const counts={};for(let y=Number(minDate.slice(0,4));y<=Number(maxDate.slice(0,4));y++)for(let m=1;m<=12;m++){const k=`${y}-${String(m).padStart(2,'0')}`;if(k>=minDate.slice(0,7)&&k<=maxDate.slice(0,7))counts[k]=0}filtered.forEach(r=>{const k=r.date?.slice(0,7);if(k in counts)counts[k]++});const max=Math.max(1,...Object.values(counts));$('timeline').replaceChildren();Object.entries(counts).forEach(([month,n])=>{const b=document.createElement('button');b.className='bar'+(!n?' empty-bar':'');b.style.height=`${Math.max(3,n/max*100)}%`;b.title=`${month}：${fmt(n)} 条`;b.setAttribute('aria-label',b.title);b.onclick=()=>{$('from').value=month+'-01';const [y,m]=month.split('-').map(Number);$('to').value=`${month}-${new Date(y,m,0).getDate()}`;apply()};$('timeline').append(b)});$('chart-start').textContent=minDate.slice(0,7);$('chart-end').textContent=maxDate.slice(0,7)}
