function updateColors(located){const mode=$('color-mode').value,counts=new Map();for(const r of located){const k=keyOf(r);counts.set(k,(counts.get(k)||0)+1)}let keys;if(mode==='unit'){keys=selected.unit.size&&selected.unit.size<optionLists.unit.length?[...selected.unit].sort():[...counts.keys()].filter(k=>k!=='未知').sort((a,b)=>counts.get(b)-counts.get(a)).slice(0,10)}else keys=mode==='category'?Object.keys(names):Object.keys(statuses);colorMap=new Map(keys.map((k,i)=>[k,mode==='status'?colors[k]:(i<palette.length?palette[i]:`hsl(${(i*137.508)%360} 62% 42%)`)]));colorMap.set('未知','#87919b');$('legend').replaceChildren();let other=0;for(const [k,n]of counts){if(!colorMap.has(k)){other+=n;continue}const row=document.createElement('div');row.className='legend-entry';row.innerHTML=`${mode==='category'?`<span class="equipment-icon" style="color:${colorMap.get(k)}">${equipmentMarkup(k)}</span>`:`<i style="background:${colorMap.get(k)}"></i>`}<span>${escape(mode==='category'?(names[k]||k):mode==='status'?(statuses[k]||k):k)}</span><b>${fmt(n)}</b>`;$('legend').append(row)}if(other){const row=document.createElement('div');row.className='legend-entry';row.innerHTML=`<i style="background:#87919b"></i><span>其他部队</span><b>${fmt(other)}</b>`;$('legend').append(row)}for(const r of located){const color=pointColor(r);dotMarkers.get(r.id).setStyle({fillColor:color})}}
